// Üretilen dosya: tool/ozgun/uret.py. Sanat · Antik Çağ ve Orta Çağ görsel sanatları: Mezopotamya, Mısır, Yunan, Roma ve Bizans (kabartmalar, Dor-İyon-Korint düzenleri, mozaik, fresk, ikona) (kolay).
const ozArt17Kolay = <(String, String, List<String>, String)>[
  ('Antik Yunan Arkaik Dönemi\'nde sol ayağı hafifçe önde, kolları yanlarda yumruk şeklinde sıkılı olarak ayakta betimlenen çıplak genç erkek heykellerine ne ad verilir?', 'Kuros', ['Kore heykelleri', 'Karyatid sütunları', 'Apoksiomenos tipi'], 'Arkaik Dönem\'in çıplak genç erkek heykelleri Kuros, giyimli genç kız heykelleri ise Kore olarak adlandırılır.'),
  ('Antik Yunan Arkaik Dönem heykeltıraşlığında renkli peplos veya khiton giysileri içinde ayakta duran genç kadın heykellerine verilen ad nedir?', 'Kore', ['Kuros', 'Kanefor', 'Nike'], 'Arkaik Dönem\'de tapınaklara adak olarak sunulan giyimli genç kadın heykellerine Kore adı verilir.'),
  ('Arkaik Dönem kuros ve kore heykellerinin yüzlerinde görülen, figüre canlılık ve yaşam enerjisi verme amacı taşıyan hafif tebessüm ifadesi sanat tarihinde nasıl adlandırılır?', 'Arkaik gülümseme', ['Klasik dinginlik', 'Helenistik patos', 'Kontrapost ifade'], 'MÖ 6. yüzyıl Yunan heykellerinde dudak kenarlarının yukarı kıvrılmasıyla oluşturulan simgesel canlılık ifadesine Arkaik gülümseme denir.'),
  ('Antik Yunan mimarisinde sütun kaidesi bulunmayan, yivli gövdesi doğrudan stylobat üzerine oturan ve yastık biçimli sade başlığa sahip en erken mimari düzen hangisidir?', 'Dor düzeni', ['İyon düzeni', 'Korint düzeni', 'Toskana düzeni'], 'Dor düzeni kaidesiz sütunları, keskin yivleri ve sade ekhinus-abakus başlığıyla ağırbaşlı ve sağlam bir görünüme sahiptir.'),
  ('Sütun başlığında koç boynuzunu veya kıvrılmış parşömen tomarını andıran iki yan sarmal (volüt) bulunan Antik Yunan mimari düzeni hangisidir?', 'İyon düzeni', ['Dor düzeni', 'Korint düzeni', 'Kompozit düzen'], 'Batı Anadolu kökenli İyon düzeni, sütun kaidesi kullanımı ve volütlü (sarmallı) zarif başlıklarıyla tanınır.'),
  ('Sütun başlığı kenger (akanthus) yapraklarıyla zengin biçimde süslenen ve ilk kez Klasik Dönem sonlarında ortaya çıkıp Helenistik ve Roma dönemlerinde yaygınlaşan düzen hangisidir?', 'Korint düzeni', ['Dor düzeni', 'İyon düzeni', 'Eol düzeni'], 'Mimar ve heykeltıraş Kallimakhos tarafından tasarlandığı rivayet edilen Korint başlığı, katmanlı akanthus yapraklarıyla karakterize edilir.'),
  ('Atina Akropolisi\'nde bulunan Erechtheion Tapınağı\'nın güney sundurmasında sütun yerine çatı saçaklığını başları üzerinde taşıyan kadın heykellerine ne ad verilir?', 'Karyatid', ['Atlant', 'Kuros', 'Akroter'], 'Mimaride sütun işlevi gören kadın heykellerine Karyatid, erkek heykellerine ise Atlant veya Telamon denir.'),
  ('Klasik Dönem heykeltıraşlığının en ünlü eserlerinden biri olan ve tam fırlatma anındaki atletin bükülmüş gövdesini donduran "Diskobolos" (Disk Atan Atlet) kimin eseridir?', 'Myron', ['Polykleitos', 'Pheidias', 'Praksiteles'], 'MÖ 450 civarında Myron tarafından bronzdan dökülen Diskobolos, hareketin en gerilimli denge anını (rhythmos) yakalayan başyapıttır.'),
  ('Heykeltıraşlıkta vücut ağırlığının tek bacak üzerine verilmesiyle kalça ve omuz eksenlerinin birbirine zıt açılarla eğim kazandığı doğal duruş biçimine ne ad verilir?', 'Kontrapost', ['İzosefali', 'Frontalite', 'Anakronizm'], 'İtalyanca "karşıt duruş" anlamına gelen kontrapost (contrapposto), bacaklar ve omuzlar arasındaki çapraz gerilim-gevşeme dengesini ifade eder.'),
  ('Atina Akropolisi\'nin yeniden inşasını yöneten, Parthenon\'un heykel programını tasarlayan ve devasa Athena Parthenos ile Olympia\'daki Zeus heykellerini yapan usta kimdir?', 'Pheidias', ['Praksiteles', 'Kallikrates', 'Mnesikles'], 'Perikles döneminin baş sanatçısı Pheidias, Yüksek Klasik Dönem\'in anıtsal ve idealize tanrı tasvirlerinin yaratıcısıdır.'),
  ('Antik Yunan seramik sanatında MÖ 10. ve 8. yüzyıllar arasında vazo yüzeylerinin menderes (meander), üçgen, dama tahtası ve şematik silüet figürlerle bezendiği dönem hangisidir?', 'Geometrik Dönem', ['Oryantalizan Dönem', 'Klasik Dönem', 'Helenistik Dönem'], 'Atina\'daki Dipylon Mezarlığı\'ndan çıkan dev krater ve amforalarla tanınan bu erken evreye Geometrik Dönem denir.'),
  ('Siyah figür tekniğiyle üretilen Antik Yunan vazolarında figürlerin siyah, arka planın ise kırmızımsı turuncu görünmesi nasıl sağlanmıştır?', 'Kil astarla çizilen figürlerin fırınlamanın indirgenme ve yükseltgenme evrelerinde siyaha dönüşmesiyle', ['Pişirilmiş vazonun üzerine kömür karası yağlı boya sürülerek figürlerin sonradan fırçayla boyanmasıyla', 'Siyah bazalt taşından öğütülen tozun hamurun yalnızca dış yüzeyine sıcak mumla yapıştırılmasıyla', 'Vazonun tamamının katrana batırılıp kuruduktan sonra arka planın zımparayla kazınarak açılmasıyla'], 'Antik Yunan vazo resminde boya değil, demir oksitçe zengin sıvı kil astar (glazür) kullanılır; üç aşamalı fırınlamada (oksijenli-oksijensiz-oksijenli) astarlı yerler siyahlaşır, gözenekli kil gövde kırmızı kalır.'),
  ('Siyah figürlü vazolarda sanatçının siyah silüet halindeki figürlerin kas, giysi kıvrımı, göz ve zırh gibi iç ayrıntılarını belirtmek için kullandığı temel yöntem nedir?', 'Sivri metal bir uçla siyah astarı kazıyarak alttaki kil rengini ortaya çıkarmak', ['Siyah yüzeyin üzerine fırçayla altın varak ve kurşunlu mavi boya çizgileri çekmek', 'Vazo henüz yaşken mühür silindirleri bastırarak kabartma çizgiler oluşturmak', 'İç detayları tamamen boş bırakıp yalnızca figürün dış konturuyla yetinmek'], 'Siyah figür tekniğinde iç detaylar ince sivri bir kalemle (stilus) kazınarak yapılır, ayrıca kadın teni için beyaz, bazı detaylar için morumsu kırmızı ek renk sürülürdü.'),
  ('MÖ 530 civarında Atina\'da geliştirilen kırmızı figür tekniğinin siyah figür tekniğine göre çalışma prensibi aşağıdakilerden hangisidir?', 'Arka planın siyaha boyanıp figürlerin kil renginde bırakılması ve iç detayların ince fırçayla çizilmesi', ['Vazonun tamamının beyaz astarla kaplanıp figürlerin parlak kırmızı lakeyle kabartma yapılması', 'Kırmızı boyalı figürlerin siyah hamurlu kil vazo üzerine soğuk fresk yöntemiyle işlenmesi', 'Figürlerin iç detaylarının daha derin oyularak gümüş tellerle kakma yapılması'], 'Kırmızı figür tekniğinde süreç tersine çevrilir: figür rezerve edilerek kil renginde bırakılır, zemin siyah astarla örtülür ve anatomik çizgiler kazıma yerine esnek fırçayla çizilir.'),
  ('Antik Yunan seramik kap formlarından iki kulplu, dar boyunlu, şarap ve zeytinyağı gibi sıvı ya da tahıl ürünlerini taşımak ve depolamak için kullanılan kap hangisidir?', 'Amfora', ['Kyliks', 'Krater', 'Oinokhoe'], 'İki kulpludan türeyen "amfora" (amphiphoreus), antik Akdeniz dünyasının en yaygın taşıma ve depolama kabıdır; Panathenaia oyunlarında da ödül olarak verilirdi.'),
  ('Antik Yunan şölenlerinde (symposion) şarap ile suyun karıştırılması için kullanılan geniş ağızlı büyük kap formuna ne ad verilir?', 'Krater', ['Hydria', 'Alabastron', 'Pyksis'], 'Antik Yunanlılar şarabı sek içmeyip suyla karıştırdıkları için şölenlerin merkezinde geniş ağızlı kraterler yer alırdı.'),
  ('Geç Klasik Dönem\'de (MÖ 4. yüzyıl) tanrıçayı ilk kez tamamen çıplak olarak banyoya girerken betimleyen "Knidos Afroditi" heykelinin yaratıcısı kimdir?', 'Praksiteles', ['Myron', 'Kalamis', 'Kritios'], 'Atinalı heykeltıraş Praksiteles, Knidos kenti için yaptığı Afrodit heykeliyle anıtsal kadın çıplaklığını Yunan sanatına kazandırmıştır.'),
  ('Büyük İskender\'in MÖ 323\'teki ölümünden MÖ 31 Actium Savaşı\'na kadar uzanan Helenistik Dönem heykeltıraşlığının Klasik Dönem\'den en belirgin farkı nedir?', 'Klasik idealizm ve dinginlik yerine dramatik coşku, acı, yaşlılık, çocukluk ve bireysel gerçekçiliğin ön plana çıkması', ['İnsan anatomisi araştırmalarının bırakılarak tamamen soyut ve geometrik idol heykellerine geri dönülmesi', 'Hareketli duruşların terk edilip kolları gövdeye yapışık cephesel kuros tipinin yeniden tek kural haline gelmesi', 'Heykel yapımında mermer ve bronzun yasaklanarak yalnızca fildişi minyatür heykelciklerin üretilmesi'], 'Helenistik sanat; sarhoş yaşlı kadın, uyuyan Eros, can çekişen Galyalı gibi toplumun her kesimini, aşırı duyguları (pathos) ve tiyatral hareketi konu edinmiştir.'),
  ('Semadirek Adası\'nda bulunan, bir geminin pruvasına konmuş halde rüzgara karşı dalgalanan ıslak giysileriyle zafer tanrıçasını betimleyen ünlü Helenistik başyapıt hangisidir?', 'Semadirek Nike\'si', ['Milo Venüsü', 'Knidos Afroditi', 'Atina Nike\'si'], 'Louvre Müzesi\'nde sergilenen MÖ 190 civarına tarihli Semadirek Kanatlı Zafer (Nike) heykeli, mekan, rüzgar ve hareketin en görkemli Helenistik sentezidir.'),
  ('Troya rahibi ile iki oğlunun denizden çıkan dev yılanlar tarafından boğulma anındaki ızdırabını betimleyen Rodos ekolüne ait ünlü Helenistik heykel grubu hangisidir?', 'Laokoon ve Oğulları', ['Farnese Boğası', 'Ölen Galyalı', 'Pergamon Sunağı'], 'Rodoslu heykeltıraşlar Agesandros, Polydoros ve Athenodoros tarafından yapılan Laokoon grubu, fiziksel ve ruhsal acının (pathos) doruk noktasıdır.'),
  ('Ege Denizi\'ndeki Melos Adası\'nda bulunan, belden yukarısı çıplak, kalçasından dökülen kumaş kıvrımları ve sarmal duruşuyla Klasik ve Helenistik özellikleri birleştiren ünlü heykel hangisidir?', 'Milo Venüsü', ['Peplos Kore', 'Hera Khiramyes', 'Kirene Afroditi'], 'MÖ 130-100 civarında Antiokheialı Aleksandros tarafından yontulan Milo Venüsü, Klasik yüz dinginliğini Helenistik sarmal gövde kurgusuyla harmanlar.'),
  ('Antik Yunan heykelleri ve tapınak mimarisi hakkında Rönesans\'tan itibaren yaygınlaşan "saf beyaz mermer" algısına karşın arkeolojik pigment analizlerinin kanıtladığı tarihsel gerçek nedir?', 'Heykellerin ve tapınak kabartmalarının canlı kırmızı, mavi, sarı, siyah ve yaldız renklerle boyandığı', ['Yunanlıların beyaz mermeri çirkin bulup tüm tapınakları siyah ziftle kapladığı', 'Renk kullanımının yalnızca köle mezarlarında izin verilip tapınaklarda kesinlikle yasaklandığı', 'Yalnızca Helenistik Dönem\'in son on yılında boya kullanılıp öncesinde taşın doğal bırakıldığı'], 'Antik Yunan heykelleri ve tapınaklarının triglif, metop ve alınlıkları "polikromi" (çok renklilik) geleneğiyle parlak mineral boyalar ve balmumu (ganosis) ile renklendirilmiştir.'),
  ('Antik Yunan tapınaklarında kutsal kült heykelinin korunduğu ana iç odaya mimarlık terminolojisinde ne ad verilir?', 'Naos', ['Pronaos', 'Opisthodomos', 'Peristasis'], 'Tapınağın kalbi sayılan ve tanrı heykelinin yer aldığı kapalı mekana Yunanca Naos (Latince Cella) denir.'),
  ('Bir Yunan tapınağında ana kutsal odanın (naos) önünde yer alan, yan duvarların uzantıları (antalar) ve ön sütunlarla sınırlanan giriş sundurmasına ne ad verilir?', 'Pronaos', ['Stylobat', 'Krepis', 'Timpanon'], '"Naos\'un önü" anlamına gelen pronaos, kutsal odaya geçmeden önceki yarı açık ön giriş holüdür.'),
  ('Atina Akropolisi\'nin batı yamacında Mnesikles tarafından MÖ 437-432 yılları arasında inşa edilen anıtsal sütunlu giriş kapısı yapısına ne ad verilir?', 'Propylaia', ['Erechtheion', 'Parthenon', 'Odeion'], 'Dor ve İyon sütunlarını bir arada kullanan görkemli Akropolis giriş kompleksine Propylaia denir.'),
  ('Dünyanın Yedi Harikası\'ndan biri sayılan, Arkaik evresi Kroisos\'un desteğiyle Khersiphron tarafından yapılan ve yangından sonra Helenistik Dönem\'de yeniden yükseltilen 127 sütunlu İyon tapınağı nerededir?', 'Efes (Artemis Tapınağı)', ['Milet (Athena Tapınağı)', 'Sardes (Kybele Tapınağı)', 'Bergama (Trajan Tapınağı)'], 'Efes Artemis Tapınağı (Artemision), alt tamburları kabartmalı sütunları (columnae caelatae) ve anıtsal dipteros planıyla antik dünyanın en ünlü yapılarındandır.'),
  ('Antik Yunan\'da şarap içmek için kullanılan, sığ ve geniş gövdeli, iki yan kulplu ve ince ayaklı kadeh formuna (iç kısmındaki daireye tondo resmi yapılan kaba) ne ad verilir?', 'Kyliks', ['Lekythos', 'Amfora', 'Pithos'], 'Şölenlerde elden ele dolaşan sığ içki kadehi kylikslerin iç tabanındaki dairesel alana (tondo) ressamlar şarap bittikçe ortaya çıkan ustalık sahneleri çizerdi.'),
  ('Büyük İskender portrelerinde alnın ortasından yukarı doğru iki tutam halinde şahlanarak ayrılan ve hükümdarın aslan yelesini andıran tanrısal gücünü simgeleyen saç biçimine ne ad verilir?', 'Anastole', ['Krobylos', 'Peplos', 'Himatyon'], 'Lysippos\'un belirlediği İskender ikonografisinde alından yukarı kabaran saç buklelerine "anastole" denir; başın hafif yana eğimi ve nemli bakışlarla tamamlanır.'),
  ('Antik Yunan tiyatro mimarisinde koronun dans edip şarkı söylediği merkezdeki dairesel alana ve izleyicilerin oturduğu yarım daire biçimli yamaç basamaklarına sırasıyla ne ad verilir?', 'Orkestra ve Koilon', ['Skene ve Proskenion', 'Parodos ve Diazoma', 'Pronaos ve Opisthodomos'], 'Yunan tiyatrosunun çekirdeği tam daire planlı orkestradır; doğal tepe yamacına oyulan izleyici basamaklarına koilon (Roma\'da cavea), sahne binasına ise skene denir.'),
  ('Antik Yunan kentlerinde agoranın (çarşı meydanının) kenarlarını sınırlayan, halkı güneş ve yağmurdan koruyan, önü boydan boya sütunlu, arkası kapalı uzun galeri yapılarına ne ad verilir?', 'Stoa', ['Tholos', 'Prytaneion', 'Stadion'], 'Atina Agorası\'ndaki Attalos Stoası gibi uzun sütunlu revaklar ticaret, sohbet ve felsefe okulları (Stoacılık adını buradan alır) için kamusal mekan sağlamıştır.'),
  ('Atina yakınlarındaki Sounion Burnu\'nda denize dik inen kayalıkların tepesinde yükselen, denizcilere yol gösteren MÖ 444-440 tarihli zarif Dor tapınağı hangi tanrıya adanmıştır?', 'Poseidon', ['Hephaistos', 'Dionysos', 'Ares'], 'Denizler tanrısı Poseidon\'a adanan Sounion Tapınağı, ince oranlı beyaz mermer Dor sütunları (16 yivli) ile Ege\'den dönen gemicileri selamlayan simgesel bir yapıdır.'),
  ('Antik Yunan vazo resminde ve tapınak kabartmalarında sıkça betimlenen, elinde aslan postu ve budaklı sopasıyla on iki zorlu görevi (dodekathlos) yerine getiren yarı tanrı kahraman kimdir?', 'Herakles', ['Perseus', 'Bellerophontes', 'Orpheus'], 'Olympia Zeus Tapınağı\'nın on iki metopunda da maceraları tek tek işlenen Herakles, Nemea aslanı postu ve gürzüyle Yunan sanatının en popüler kahramanıdır.'),
  ('Arkaik Dönem tapınak alınlıklarında, kalkanlarda ve çatı antefikslerinde kötülüğü uzaklaştırıcı (apotropaik) amaçla dilini çıkarmış ve saçları yılanlarla çevrili olarak betimlenen figür hangisidir?', 'Gorgon', ['Siren', 'Nike', 'Nereid'], 'Bakanı taşa çevirdiğine inanılan Medusa başı (Gorgoneion), Korfu Tapınağı alınlığından Athena\'nın zırhına (aegis) kadar koruyucu tılsım olarak kullanılmıştır.'),
  ('Arkaik Dönem Yunan vazo resminde (ve Mısır etkisinde) insan figürlerinin baş ve bacaklarının yandan (profilden), göz ve göğüs kafesinin ise cepheden birleştirilerek çizilmesine ne ad verilir?', 'Bileşik (kompozit) bakış açısı', ['Atmosferik (hava) perspektifi', 'Doğrusal (lineer) kaçış perspektifi', 'Noktasal (puantilist) boyama'], 'Kırmızı figür öncülerinin rakursi (kısaltım) devrimine kadar Arkaik figürlerde en tanınır açıları birleştiren profilden baş-ayak ve cepheden gövde-göz şeması kullanılmıştır.'),
  ('Ege adalarından Rodos\'un liman girişi yakınlarında Lindoslu Khares tarafından MÖ 3. yüzyılda bronzdan inşa edilen ve Dünyanın Yedi Harikası arasında sayılan 30 metrelik dev Helenistik heykel hangi tanrıyı betimliyordu?', 'Güneş Tanrısı Helios', ['Deniz Tanrısı Poseidon', 'Savaş Tanrısı Ares', 'Haberci Tanrı Hermes'], 'MÖ 280 civarında tamamlanıp MÖ 226 depreminde yıkılan Rodos Kolossosu, adanın koruyucu tanrısı Helios\'un anıtsal bronz heykeliydi.'),
  ('Sümer kent devletlerinde giderek küçülen teraslar hâlinde yükselen ve en üst katında tanrı evi bulunan tapınak yapılarına ne ad verilir?', 'Ziggurat', ['Mastaba tipi mezar kompleksi', 'Hipostil sütunlu kabul salonu', 'Megaron planlı saray avlusu'], 'Sümer mimarisinin en karakteristik dini yapısı olan zigguratlar, basamaklı teraslar şeklinde yükselir ve en üstünde kutsal tapınak odası yer alır.'),
  ('Mezopotamya mimarisinde taş yerine ağırlıklı olarak güneşte kurutulmuş kerpiç tuğla kullanılmasının temel nedeni nedir?', 'Bölgedeki alüvyonlu ovalarda taş ocaklarının çok az, kil yataklarının ise bol olması', ['Kerpiç malzemenin sert granitten çok daha dayanıklı ve su geçirmez nitelik taşıması', 'Dini yasaların tapınak inşaatlarında doğadan çıkarılan taş kullanımını kesin biçimde yasaklaması', 'Sümerli ustaların taş yontma aletlerini henüz üretemeyecek kadar geri bir teknolojide kalması'], 'Fırat ve Dicle arasındaki alüvyonlu Mezopotamya topraklarında doğal taş kıtlığı yaşandığından kil esaslı kerpiç ana yapı malzemesi olmuştur.'),
  ('Asur saray kapılarını kötü ruhlardan korumak amacıyla yerleştirilen insan başlı, kanatlı boğa veya aslan heykellerine ne ad verilir?', 'Lamassu', ['Uşabti', 'Karyatid', 'Kuros'], 'Asur mimarisinde saray ve kent kapılarının iki yanına koruyucu cin olarak yerleştirilen anıtsal karışık varlık heykellerine Lamassu denir.'),
  ('Üst kısmında Kral Hammurabi\'nin Güneş ve Adalet Tanrısı Şamaş\'tan kanunları alışını gösteren kabartmanın bulunduğu bazalt taş anıt hangisidir?', 'Hammurabi Kanun Steli', ['Siyah Dikilitaş', 'Behistun Yazıtı', 'Kadeş Antlaşması Tableti'], 'Diyorit/bazalt taştan yapılan Hammurabi Steli\'nin tepesinde tahtta oturan tanrı Şamaş ile ayakta duran kral Hammurabi\'nin yüksek kabartması yer alır.'),
  ('Mezopotamya\'da mülkiyet belirlemek ve kil tabletleri onaylamak için kendi ekseni etrafında yuvarlanarak kesintisiz kabartma izi bırakan nesne nedir?', 'Silindir mühür', ['Skarabe mühür', 'Damga sikke', 'Ostrakon parçası'], 'Sümerlerden itibaren yaygınlaşan silindir mühürler, ıslak kil üzerinde yuvarlandığında mitolojik ve ritüel konulu şerit kabartmalar oluşturur.'),
  ('Günümüze en iyi korunmuş örneklerinden biri ulaşan ve III. Ur Hanedanı kurucusu Ur-Nammu tarafından Ay Tanrısı Nanna onuruna yaptırılan yapı hangisidir?', 'Ur Zigguratı', ['Etemenanki Kulesi', 'Çoğa Zenbil Tapınağı', 'Akkaraguf Zigguratı'], 'Irak\'ın güneyindeki antik Ur kentinde yer alan Büyük Ur Zigguratı, Ay Tanrısı Nanna için inşa edilmiş anıtsal üç rampalı bir Sümer yapısıdır.'),
  ('Anadolu\'da Çorum\'un Boğazkale ilçesinde yer alan ve Hitit İmparatorluğu\'nun başkenti olan antik kentteki sur girişlerinden en ünlülerinden biri hangisidir?', 'Aslanlı Kapı', ['İştar Kapısı', 'Hadrian Kapısı', 'Milet Pazar Kapısı'], 'Hattuşa surlarında dışa doğru kükreyen aslan ön gövdelerinin kapı söve taşlarına yontulduğu Aslanlı Kapı, Hitit anıtsal taş işçiliğinin simgesidir.'),
  ('Anadolu\'da dünyanın bilinen en erken neolitik yerleşmelerinden olan ve ev duvarlarındaki boğa başı (bukranion) ile av sahnesi resimleriyle tanınan merkez hangisidir?', 'Çatalhöyük', ['Truva', 'Sardes', 'Efes'], 'Konya Çumra yakınlarındaki Çatalhöyük, sıvalı kerpiç duvarlar üzerindeki av sahneleri, geometrik bezemeler ve sıvalı boğa kafataslarıyla ünlüdür.'),
  ('Tunç Çağı Anadolu sanatının simgelerinden olan ve mezar hediyesi olarak bırakılmış tunç "Güneş Kursları" ile geyik heykelcikleri hangi merkezde bulunmuştur?', 'Alacahöyük', ['Hattuşa', 'Nemrut Dağı', 'Perge'], 'Çorum\'daki Alacahöyük Hatti Kral Mezarları\'nda bulunan döküm tunç güneş kursları, boğa ve geyik standartları Erken Tunç Çağı maden sanatının başyapıtlarıdır.'),
  ('Friglerin Eskişehir, Kütahya ve Afyon arasındaki Dağlık Frigya bölgesinde tüf kayaları oyarak yaptıkları üçgen alınlıklı anıtsal cephelerin en ünlüsü hangisidir?', 'Midas Anıtı', ['Kral Mozoles\'in Mezarı', 'Celsus Kütüphanesi', 'Sümela Manastırı'], 'Eskişehir Han ilçesindeki Yazılıkaya vadisinde yer alan Midas Anıtı, geometrik bezemeli kaya cephesi ve tanrıça Kybele nişiyle Frig sanatının başyapıtıdır.'),
  ('Batı Anadolu\'da Lidya Krallığı\'nın başkenti Sardes ile özdeşleşen ve görsel tasarımlarında aslan-boğa mücadelesi kabartması taşıyan dünya çapındaki buluş nedir?', 'Devlet mührü taşıyan ilk madeni para', ['Baskı kalıplarıyla çoğaltılan ilk renkli kağıt banknot', 'İpek böceği kozasından dokunan ilk kraliyet halısı', 'Kum ve sodadan kalıba dökülen ilk şeffaf pencere camı'], 'Lidyalılar altın-gümüş karışımı elektrondan ve ardından saf altın/gümüşten üzerinde aslan ve boğa kabartması bulunan ilk sikkeleri basmışlardır.'),
  ('Babil kentinin merkezinde yükselen ve kutsal metinlerdeki "Babil Kulesi" anlatılarına esin kaynağı olduğu kabul edilen yedi katlı zigguratın adı nedir?', 'Etemenanki', ['Ramesseum', 'Parthenon', 'Apadana'], 'Tanrı Marduk\'un tapınak kompleksinde yer alan ve Sümerce "Gök ile Yerin Temelinin Evi" anlamına gelen Etemenanki, Babil\'in anıtsal zigguratıdır.'),
  ('Mezopotamya mimarisinde kapı ve koridor açıklıklarını geçmek için uzun taş kirişler yerine gerçek kemer ve tonoz sistemlerinin erken dönemde geliştirilmesinin nedeni nedir?', 'Küçük boyutlu kerpiç ve pişmiş tuğlalarla geniş açıklıkları kapatmanın kemer tekniğini zorunlu kılması', ['Bölgede yüzlerce metre boyunda tek parça sedir ağacı gövdelerinin her ovada kendiliğinden yetişmesi', 'Kemerli yapıların deprem sırasında kesinlikle yıkılmayacağını kanıtlayan modern çelik iskeletlerin kullanılması', 'Mısırlı piramit işçilerinin Babil\'e göç ederek kireçtaşı lentoları tuğlayla değiştirmeyi yasaklaması'], 'Uzun taş lentolar ve ahşap kirişler Mezopotamya\'da nadir bulunduğundan, küçük tuğlaları birbirine kilitleyerek açıklık geçmeyi sağlayan kemer ve tonoz mimarisi gelişmiştir.'),
  ('Mezopotamya\'nın kuzeydoğusu ve İran sınırında gelişen Elam uygarlığından günümüze kalan, sırlı tuğlalarıyla da bilinen en büyük ziggurat hangisidir?', 'Çoğa Zenbil Zigguratı', ['Luksor Tapınağı', 'Gize Piramidi', 'Knossos Sarayı'], 'Elam Kralı Untaş-Napirişa tarafından Dur-Untaş kentinde inşa ettirilen Çoğa Zenbil, Mezopotamya dışındaki en iyi korunmuş ve en büyük ziggurat örneğidir.'),
  ('Anadolu\'da Hititlerden önce Asurlu tüccarların kurduğu ticaret kolonilerinin (Karum) merkezi olan ve yazılı kil tabletlerin yanı sıra hayvan biçimli kaplarıyla (riton) tanınan yer neresidir?', 'Kültepe', ['Çatalhöyük', 'Göbeklitepe', 'Afrodisias'], 'Kayseri yakınlarındaki Kültepe-Kaniş Karumu, Anadolu\'da yazılı tarihin başladığı merkez olup aslan, kartal ve antilop biçimli parlak astarlı ritonlarıyla ünlüdür.'),
  ('Mezopotamya kabartmalarında hükümdarın elinde tuttuğu "halka ve asa" sembolleri genel olarak hangi kavramları temsil eder?', 'Adil yönetim yetkisini ve krallık iktidarını', ['Deniz ticareti tekelini ve gemicilik bilgisini', 'Müzik korosu şefliğini ve şölen düzenini', 'Hekimlik loncasını ve bitkisel şifa gücünü'], 'Hammurabi Steli ve Ur-Nammu Steli gibi anıtlarda tanrının krala uzattığı ölçü ipi/halkası ve değnek (asa), ilahi adaletle inşa etme ve hükmetme yetkisinin simgeleridir.'),
  ('Anadolu\'da Adıyaman il sınırlarındaki Nemrut Dağı zirvesinde yer alan devasa tanrı-kral heykelleri hangi antik krallık döneminde yaptırılmıştır?', 'Kommagene Krallığı', ['Hitit İmparatorluğu', 'Urartu Krallığı', 'Lidya Krallığı'], 'Kral I. Antiokhos tarafından MÖ 1. yüzyılda yaptırılan Nemrut Dağı tümülüsü ve devasa kireçtaşı heykeller, Doğu (Pers) ve Batı (Helenistik) sanat üsluplarının sentezidir.'),
  ('Sümer heykeltıraşlığında figürlerin ellerini göğüs hizasında birleştirmiş olarak ayakta veya otururken tasvir edilmesi hangi davranışı ifade eder?', 'Tanrı huzurunda dua ve saygı duruşunu', ['Düşman ordusuna teslim olma işaretini', 'Ticari pazarlıkta yemin etme geleneğini', 'Kraliyet mahkemesinde suçsuzluğu savunmayı'], 'Mezopotamya adak heykellerinde (Tell Asmar, Mari ve Gudea heykellerinde) göğüs önünde kavuşturulmuş eller, tanrıya sonsuz bağlılık ve dua pozisyonudur.'),
  ('Güneydoğu Anadolu\'da Fırat Nehri kıyısındaki Zeugma Antik Kenti\'nde Roma Dönemi villalarının tabanından çıkarılan dünyaca ünlü görsel sanat eseri hangisidir?', 'Çingene Kızı Mozaiği', ['İskender Lahdi', 'Yorgun Herakles Heykeli', 'Kaplumbağa Terbiyecisi'], 'Gaziantep\'teki Zeugma Antik Kenti\'nde bulunan ve bakışlarıyla ünlü olan "Çingene Kızı" (muhtemelen Gaia veya Mainad), Anadolu\'daki antik mozaik sanatının simgesidir.'),
  ('Hitit kaya anıtlarının (Fıraktin, Hanyeri, İvriz, Karabel gibi) genellikle su kaynakları ve doğal dağ geçitlerinin yanındaki kayalara yontulmasının nedeni nedir?', 'Hem suyun kutsallığını onurlandırmak hem de ticaret ve ordu güzergâhlarında egemenlik sınırlarını işaretlemek', ['Kaya yüzeylerinin yalnızca akarsu kenarlarında parmakla kazınacak kadar yumuşak çamura dönüşmesi', 'Başkentteki saray duvarlarında taş kabartma yapacak hiçbir boş alanın kalmamış olması', 'Güneş ışığının vadi içlerine hiç girmemesi sayesinde boyaların solmasını önlemek istemeleri'], 'Hitit kaya kabartmaları kutsal pınarlarla dinsel bağ kurarken aynı zamanda imparatorluğun stratejik dağ geçitlerinde siyasal varlığını ilan eder.'),
  ('Eski Mısır\'da piramitlerden önce kral ve soylular için yapılan, kesik piramit görünümlü, eğimli duvarlı dikdörtgen planlı mezar yapılarına ne ad verilir?', 'Mastaba', ['Ziggurat', 'Tümülüs', 'Hipogeum'], 'Arapça "sedir/bank" anlamına gelen mastaba, yeraltındaki mezar odası üzerine kerpiç veya taştan inşa edilen erken dönem Mısır mezar tipidir.'),
  ('Sakkara\'da Firavun Zoser için tarihte adı bilinen ilk mimar İmhotep tarafından altı basamaklı olarak inşa edilen ilk anıtsal taş piramit hangisidir?', 'Zoser Basamaklı Piramidi', ['Keops Büyük Piramidi', 'Kefren Piramidi', 'Mikerinos Piramidi'], 'III. Hanedan firavunu Zoser için mimar İmhotep\'in mastabaları üst üste küçülterek tasarladığı Sakkara Basamaklı Piramidi, Mısır\'ın ilk dev taş yapısıdır.'),
  ('Kahire yakınlarındaki Gize Platosu\'nda yer alan üç büyük klasik piramitten en yüksek ve hacimce en büyük olanı hangi firavun adına yaptırılmıştır?', 'Keops', ['Tutankhamun', 'II. Ramses', 'Akhenaton'], 'IV. Hanedan firavunu Keops (Khufu) için inşa edilen Büyük Piramit, antik dünyanın yedi harikasından ayakta kalan tek yapıdır.'),
  ('Gize\'deki Kefren Piramidi\'nin önünde uzanan, aslan gövdeli ve firavun (insan) başlı dev yekpare kireçtaşı heykele ne ad verilir?', 'Büyük Sfenks', ['Büyük Lamassu', 'Muşhuşşu Anıtı', 'Memnon Heykeli'], 'Doğal kireçtaşı kayalığının yontulmasıyla oluşturulan Gize\'deki Büyük Sfenks, aslanın gücüyle firavunun (muhtemelen Kefren) bilgeliğini birleştirir.'),
  ('Eski Mısır heykel sanatında ayakta duran veya oturan figürün baş, boyun ve omurgasından geçen dikey eksenin sağa sola hiç bükülmeden dimdik verilmesi hangi yasadır?', 'Frontalite (cephedenlik) yasası', ['Kontrapost (karşıt duruş) yasası', 'Barok diyagonal hareket yasası', 'Gotik dikey incelme yasası'], 'Arkaik heykel sanatlarına egemen olan frontalite yasasında heykel tam karşıdan izlenmek üzere simetrik ve omurgası bükülmez biçimde kurgulanır.'),
  ('Yeni Krallık Dönemi\'nde çok tanrılı Amon rahipliğine karşı çıkarak tek güneş kursu Aton inancını getiren ve sanatta radikal bir gerçekçilik başlatan firavun kimdir?', 'IV. Amenhotep', ['III. Thutmose', 'II. Pepi', 'Kleopatra'], 'Adını Akhenaton olarak değiştiren IV. Amenhotep, başkenti Akhetaton\'a (Tell el-Amarna) taşıyarak Mısır sanatında Amarna Üslubu\'nu başlatmıştır.'),
  ('Amarna Dönemi heykeltıraşlığının en ünlü eseri olan ve heykeltıraş Thutmose\'nin atölyesinde bulunan boyalı kireçtaşı büst hangi Mısır kraliçesine aittir?', 'Kraliçe Nefertiti', ['Kraliçe Hatşepsut', 'Kraliçe Nefertari', 'Kraliçe Tiye'], 'Alman arkeolog Borchardt\'ın Tell el-Amarna\'da heykeltıraş Thutmose\'nin atölyesinde bulduğu boyalı kireçtaşı Nefertiti Büstü, antik portre sanatının şaheseridir.'),
  ('Krallar Vadisi\'nde soyulmadan günümüze ulaşan mezarıyla ünlenen ve on bir kilogramlık som altın, lacivert taş kakmalı ölüm maskesiyle tanınan firavun kimdir?', 'Tutankhamun', ['I. Seti', 'Kefren', 'Zoser'], '1922\'de Howard Carter tarafından KV62 numaralı mezarı keşfedilen Tutankhamun\'un altın ölüm maskesi, Eski Mısır kuyumculuk ve portre sanatının simgesidir.'),
  ('Yeni Krallık Dönemi\'nde firavunların piramit yapmayı bırakarak mezarlarını Teb\'in batı yakasındaki sarp kayalıklara gizlice oydukları nekropol alanının adı nedir?', 'Krallar Vadisi', ['Gize Platosu', 'Fayyum Vahası', 'İskenderiye Limanı'], 'Mezar soyguncularına karşı önlem olarak Yeni Krallık firavunları (XVIII.-XX. Hanedanlar) kaya içine oyulmuş uzun koridorlu mezarlarını Krallar Vadisi\'nde yaptırmıştır.'),
  ('Firavun II. Ramses tarafından Güney Mısır\'da (Nübye sınırında) dağ kayası oyularak yaptırılan ve cephesinde yirmi metrelik dört dev oturan Ramses heykeli bulunan tapınak hangisidir?', 'Ebu Simbel Tapınağı', ['Edfu Horus Tapınağı', 'Dendera Hathor Tapınağı', 'Kom Ombo Tapınağı'], 'Asvan Barajı suları altında kalmaması için uluslararası çabayla taşınan Ebu Simbel Büyük Tapınağı, cephesindeki dört dev II. Ramses kolosuyla tanınır.'),
  ('Mısır tapınaklarının girişinde yer alan, yukarı doğru hafifçe daralan ikiz kule görünümlü anıtsal taş cephe kapılarına ne ad verilir?', 'Pilon', ['Propilon', 'kemerli Tak', 'Portiko'], 'İki eğimli dev kule ve aralarındaki kapıdan oluşan pilonlar, doğu-batı ufuk dağlarını (Akhet) simgeler ve üzerlerinde firavunun düşmanları kahrettiği kabartmalar yer alır.'),
  ('Mısır görsel sanatında şahin başlı olarak tasvir edilen ve yaşayan her firavunun yeryüzündeki bedenleşmesi sayılan gökyüzü ve krallık tanrısı kimdir?', 'Horus', ['Anubis', 'Thoth', 'Ptah'], 'Kefren\'in diyorit taht heykelinde de firavunun ensesini kanatlarıyla korurken görülen şahin tanrı Horus, meşru firavunluk iktidarının simgesidir.'),
  ('Eski Mısır mezarlarına ölen kişinin öteki dünyadaki tarım ve inşaat işlerini onun yerine yapması amacıyla yüzlerce adet bırakılan küçük mumya biçimli heykelciklere ne denir?', 'Uşabti', ['Kanopik', 'Skarabe', 'Ostrakon'], 'Fayans, ahşap veya taştan yapılan Uşabti ("cevap verenler") heykelcikleri, öteki dünyada Osiris hizmet çağırdığında mezar sahibi adına çalışmak için mezara konulurdu.'),
  ('Firavun başlıklarının ve maskelerinin tam alın kısmında şahlanmış biçimde yer alan ve kralı düşmanlarına ateş püskürterek koruduğuna inanılan kobra yılanı sembolüne ne ad verilir?', 'Uraeus (Kutsal Kobra)', ['Ankh (Yaşam Anahtarı)', 'Djed (İstikrar Sütunu)', 'Was (Güç Asası)'], 'Aşağı Mısır\'ın koruyucu tanrıçası Wadjet\'i temsil eden şahlanmış kobra (Uraeus), Yukarı Mısır\'ın akbabası Nekhbet ile birlikte firavun tacının alınlığında yer alır.'),
  ('Eski Mısır görsel sanatında tanrıların ellerinde tuttukları veya firavunun burnuna yaklaştırdıkları üst kısmı ilmekli haç biçimindeki "sonsuz yaşam" sembolünün adı nedir?', 'Ankh', ['Uraeus', 'Nemess', 'Pschent'], 'Üstü damla/ilmek biçimli haç olan Ankh, Eski Mısır ikonografisinde yaşam soluğunu ve ölümsüzlüğü simgeleyen en yaygın hiyeroglif semboldür.'),
  ('Roma Dönemi Mısır\'ında mumyaların yüz kısmına yerleştirilen, ahşap levha üzerine sıcak balmumu (ankostik) tekniğiyle son derece gerçekçi boyanmış portrelere ne ad verilir?', 'Fayyum Mumya Portreleri', ['Sakkara Maskeleri', 'Amarna Büstleri', 'Teb Duvar Rölyefleri'], 'MS 1.-3. yüzyıllarda Fayyum Vahası başta olmak üzere üretilen mumya portreleri, Mısır mumyalama geleneği ile Greko-Romen natüralist resim tekniğinin birleşimidir.'),
  ('Mısır firavunlarının başlarına taktıkları, omuzların iki yanından göğse doğru sarkan mavi-altın yatay çizgili keten baş örtüsüne ne ad verilir?', 'Nemes başlığı', ['Frig külahı', 'Pers tiarası', 'Defne çelengi'], 'Tutankhamun\'un altın maskesinde ve Büyük Sfenks\'te görülen çizgili kraliyet başörtüsü Nemes adını taşır.'),
  ('Eski Mısır\'da firavunların ve kraliçelerin hiyeroglifle yazılan isimlerini büyüsel olarak korumak amacıyla etrafını çevreleyen oval düğümlü ip çerçeveye ne ad verilir?', 'Kartuş', ['Madalyon', 'Rozet', 'Silindir'], 'Rosetta Taşı\'nda hiyerogliflerin çözülmesinde de kilit rol oynayan oval çerçeveli isim halkasına "kartuş" (Mısır dilinde şenu) denir.'),
  ('Teb\'in batı yakasında III. Amenhotep\'in yıkılmış morg tapınağından geriye kalan ve Yunanlıların "Memnon Devleri" adını verdiği on sekiz metrelik iki dev taş heykel kimi betimler?', 'Tahtta oturan Firavun III. Amenhotep\'i', ['Savaş arabasındaki Tanrı Marduk\'u', 'Ayakta duran Büyük İskender\'i', 'Kanatlı Tanrıça İsis\'i'], 'Luksor\'da Nil ovasına bakan Memnon Kolosları, XVIII. Hanedan\'ın en zengin döneminin firavunu III. Amenhotep\'in kuvarsit taşından dev oturan heykelleridir.'),
  ('Eski Mısır sanatında kutsal bokböceği biçiminde yontulan, sabah güneşini doğuran Khepri ile ilişkilendirilen ve alt yüzeyi mühür/tılsım olarak kullanılan nesneye ne ad verilir?', 'Skarabe', ['Silindir mühür', 'Damga fibula', 'Bulla'], 'Yeniden doğuşu ve güneşin gökyüzündeki hareketini simgeleyen skarabe (bokböceği) tılsımları, kalp skarabesi ve kraliyet hatıra mührü olarak yaygın biçimde üretilmiştir.'),
  ('Eski Mısır yazısı olan ve tapınak ile mezar duvarlarında aynı zamanda estetik bir görsel tasarım öğesi olarak kullanılan "kutsal oyma" anlamındaki resim yazısına ne ad verilir?', 'Hiyeroglif', ['Çivi yazısı', 'Linear B', 'Runik yazı'], 'Yunanca "kutsal oyma" anlamına gelen hiyeroglifler, Mısır kabartma ve resimlerinde figürlerin arasındaki boşlukları dengeli biçimde dolduran görsel sanatın ayrılmaz parçasıdır.'),
  ('Eski Mısır sanatında ibis (kelaynak) kuşu başlı veya babun biçiminde tasvir edilen; yazının, bilgeliğin ve kâtiplerin koruyucusu olan tanrı kimdir?', 'Thoth', ['Anubis', 'Horus', 'Amon'], 'Ölüler Kitabı\'ndaki kalp tartımı sahnesinde terazi sonucunu elindeki tablete kaydeden uzun kıvrık gagalı ibis başlı tanrı bilgelik tanrısı Thoth\'tur.'),
  ('Eski Mısır\'da aslan gövdeli sfenkslerin koç başlı olarak yontulmuş çeşidine (örneğin Karnak ve Luksor tapınakları arasındaki Sfenksli Yol\'da bulunanlara) ne ad verilir?', 'Kriyosfenks (Koç başlı sfenks)', ['Androsfenks (İnsan başlı sfenks)', 'Hierakosfenks (Şahin başlı sfenks)', 'Lamassu (Kanatlı insan başlı boğa)'], 'Tanrı Amon\'un kutsal hayvanı koç olduğundan, Karnak Tapınağı\'na uzanan tören yolunun iki yanında boynuzlu koç başlı sfenksler (kriyosfenks) dizilidir.'),
  ('Birçok Eski Mısır heykelinin özellikle "burun" kısmının kırık olarak günümüze ulaşmasının doğal aşınma dışındaki kasıtlı inançsal nedeni nedir?', 'Heykelin içinde yaşadığına inanılan ruhun (Ka) nefes almasını engelleyerek heykelin büyüsel gücünü etkisiz hâle getirmek', ['Mezar soyguncularının burun kısmında gizli elmas saklandığını sanarak yalnızca orayı kırması', 'Romalı askerlerin okçuluk talimlerinde heykellerin burnunu hedef tahtası yapması', 'Kireçtaşının burun ucundaki kimyasal yapısının güneş görünce kendiliğinden erimesi'], 'Mısır inancında heykel yaşayan bir varlık (ruh evi) sayıldığından, siyasi düşmanlar veya mezar soyguncuları heykelin "nefes alıp intikam almasını" önlemek için özellikle burnunu kırmıştır.'),
  ('Eski Mısır\'da Nil kıyılarında yetişen kamış benzeri bitkinin gövde liflerinin şeritler hâlinde çapraz dizilip dövülmesiyle üretilen ve üzerine resimli metinler çizilen yazı malzemesi nedir?', 'Papirüs', ['Parşömen', 'Kil tablet', 'İpek kumaş'], 'Mısır\'ın antik dünyaya ihraç ettiği papirüs ruloları, özellikle Yeni Krallık\'ta renkli vinyetlerle (resimlerle) süslü "Ölüler Kitabı" nüshalarının temel taşıyıcısı olmuştur.'),
  ('Mısır\'da aslan başlı, başında güneş kursu taşıyan korkutucu savaş, salgın ve yıkım tanrıçası olarak yüzlerce siyah granodiyorit heykeli yaptırılan tanrıça kimdir?', 'Sekhmet', ['Bastet', 'İsis', 'Nephthys'], 'Özellikle III. Amenhotep\'in Teb\'deki tapınağı ve Karnak Mut Tapınağı için yüzlerce siyah granodiyorit heykeli yontulan dişi aslan başlı tanrıça Sekhmet\'tir.'),
  ('Roma\'daki Pantheon Tapınağı\'nın devasa kubbesinin tam ortasında yer alan ve yapının iç mekanını aydınlatan dairesel açıklığa ne ad verilir?', 'Oculus', ['apsis yarım kubbesi', 'narteks giriş holü', 'peristil sütunlu avlu'], 'Latincede göz anlamına gelen oculus, Pantheon kubbesinin tepesindeki yaklaşık dokuz metre çapındaki açık aydınlatma penceresidir.'),
  ('MS 79 yılında Vezüv Yanardağı\'nın patlamasıyla küller altında kalarak duvar resimleri (freskleri) bozulmadan korunan antik Roma kenti hangisidir?', 'Pompei', ['Kartaca antik liman kenti', 'Efes antik yerleşimi', 'İskenderiye kıyı kenti'], 'Vezüv Yanardağı\'nın püskürttüğü volkanik kül tabakası Pompei ve Herculaneum kentlerindeki freskleri havayla temastan keserek korumuştur.'),
  ('Roma\'da askeri zaferleri onurlandırmak amacıyla inşa edilen, içinden muzaffer komutan ve ordusunun geçtiği anıtsal kemerli yapılara ne ad verilir?', 'Zafer Takı', ['Su kemeri', 'Bazilika tören salonu', 'Amfitiyatro gösteri alanı'], 'Roma mimarisinde zafer alaylarının geçişi ve imparatorluk propagandası için yapılan bağımsız kemerli anıtlara zafer takı denir.'),
  ('Orta Çağ boyunca Hristiyanlar tarafından yanlışlıkla ilk Hristiyan imparator Konstantin zannedildiği için eritilmekten kurtulan, Roma\'dan günümüze ulaşmış tek büyük ölçekli bronz imparatorluk atlı heykeli kime aittir?', 'Marcus Aurelius', ['Septimius Severus', 'Diocletianus', 'Nero Claudius'], 'Kapitol Tepesi\'nde sergilenmiş olan bronz Marcus Aurelius Atlı Heykeli, Konstantin sanıldığı için kilise tarafından tahrip edilmemiştir.'),
  ('Roma İmparatorluğu\'nda Hristiyanlığın yasaklı olduğu dönemlerde inananların ölülerini gömmek ve anma törenleri yapmak için yer altında kazdıkları dar koridorlu mezar galerilerine ne ad verilir?', 'Katakomp', ['Hipodrom', 'Akropol', 'Nekropol tümülüsü'], 'Özellikle Roma kenti çevresindeki tüf kayalıklara oyulan katakomplar, Erken Hristiyan duvar resimlerinin ilk örneklerini barındıran yer altı mezarlıklarıdır.'),
  ('Erken Hristiyan resimlerinde kollarını iki yana ve yukarıya doğru açarak ayakta dua eden insan figürüne ne ad verilir?', 'Orans', ['Kontrapost duruşu', 'Kuros heykel tipi', 'İkonostasis figürü'], 'Orans figürü, avuçları göğe açık biçimde ayakta dua eden dindarı ve ölümden sonra kurtuluşa eren ruhu temsil eder.'),
  ('Küçük renkli taş, mermer, pişmiş toprak veya cam küplerin harç içerisine yan yana dizilmesiyle oluşturulan resim sanatına ve bu küçük küplerin her birine sırasıyla ne ad verilir?', 'Mozaik - Tessera', ['Fresk - İntanako', 'Vitray - Kurşun kayıt', 'Enkostik - Palet'], 'Mozaik sanatında yüzeyi oluşturan küçük renkli cam veya taş parçacıklarına Latince kökenli tessera (çoğulu tesserae) denir.'),
  ('MS 5. yüzyılda Batı Roma İmparatorluğu\'nun, 6. yüzyılda ise Bizans\'ın İtalya Eksarhlığı\'nın merkezi olan ve barındırdığı Erken Hristiyan-Bizans mozaikleriyle tanınan İtalya kenti hangisidir?', 'Ravenna', ['Floransa', 'Napoli', 'Milano'], 'Adriyatik kıyısına yakın bataklıklarla korunan Ravenna; Galla Placidia, San Vitale ve Sant\'Apollinare kiliselerindeki eşsiz mozaikleriyle ünlüdür.'),
  ('MS 532-537 yıllarında İmparator I. Justinianus tarafından Konstantinopolis\'te (İstanbul) inşa ettirilen ve Bizans mimarisinin zirvesi kabul edilen Ayasofya\'nın mimarları kimlerdir?', 'Trallesli Anthemios ve Miletoslu İsidoros', ['Romalı Vitruvius ve Şamlı Apollodoros', 'Sinanlı Mimar Hayreddin ve Sedefkâr Mehmed Ağa', 'İznikli Gennadios ve Selanikli Theodoros'], 'Ayasofya, fizikçi-matematikçi (mekanikos) olan Aydınlı (Tralles) Anthemios ile Miletli İsidoros tarafından beş yıl gibi kısa bir sürede tasarlanıp inşa edilmiştir.'),
  ('Roma\'daki Kolezyum\'un (Colosseum) resmi antik adı olan "Flavianus Amfitiyatrosu" hangi imparatorluk hanedanı döneminde inşa edilmesinden kaynaklanır?', 'Flavianus Hanedanı', ['İulius-Claudius Hanedanı', 'Severuslar Hanedanı', 'Antoninler Hanedanı'], 'Kolezyum, Nero\'nun saray arazisi üzerine Flavianus hanedanının kurucusu Vespasianus tarafından başlatılmış ve oğlu Titus döneminde MS 80\'de açılmıştır.'),
  ('İmparatorluğun halka ücretsiz eğlence sunduğu araba yarışlarının düzenlendiği, ortasında "spina" adı verilen dikilitaşlı bir duvar bulunan uzun U planlı Roma yapılarına ne ad verilir?', 'Circus', ['Odeon müzik binası', 'Bazilika mahkeme salonu', 'Forum ticaret meydanı'], 'Roma\'daki Circus Maximus ve Konstantinopolis\'teki Hipodrom, dört atlı savaş arabası (quadriga) yarışlarının yapıldığı devasa yapılardır.'),
  ('Bizans İmparatorluğu\'nda 8. ve 9. yüzyıllarda dini tasvirlerin putperestlik sayılarak yasaklandığı ve mevcut tasvirlerin tahrip edildiği döneme ne ad verilir?', 'İkonoklazm', ['Rönesans Hümanizmi Dönemi', 'Paleologos Uyanışı Dönemi', 'Lale Devri Yenileşmesi'], '726-843 yılları arasında iki evre halinde yaşanan İkonoklazm, İsa, Meryem ve aziz tasvirlerinin üretilmesine ve saygı görmesine karşı çıkan dini-siyasi harekettir.'),
  ('Bizans\'ta 843 yılında İmparatoriçe Theodora öncülüğünde İkonoklazm\'ın kesin olarak sona erdirilmesi ve ikonaların kiliselere yeniden konulması olayı Ortodoks dünyasında hangi adla kutlanır?', 'Ortodoksluğun Zaferi', ['Pentekost Yortusu', 'Epifani Vaftiz Bayramı', 'Meryem\'in Göğe Kabulü'], '11 Mart 843\'te ikona yasağının kaldırılması "Ortodoksluğun Zaferi" olarak adlandırılmış ve Bizans sanatında Makedonya Rönesansı\'nın önünü açmıştır.'),
  ('Bizans sanatında sağ eliyle kutsama işareti yapan, sol elinde ise genellikle mücevherli bir İncil tutan "Evrenin Hükümdarı / Her Şeye Kadir" İsa tasvir tipine ne ad verilir?', 'Pantokrator İsa', ['Hodegetria Meryem', 'Eleusa (Şefkatli) Meryem', 'Koimesis (Uyku) sahnesi'], 'Yunanca "her şeye gücü yeten, evrenin hakimi" anlamına gelen Pantokrator, Bizans kiliselerinin ana kubbe göbeğine yerleştirilen anıtsal İsa büstüdür.'),
  ('Ayasofya\'nın iç narteksinden ana mekana açılan İmparator Kapısı üzerindeki (9. yüzyıl sonu) mozaikte, tahtta oturan Pantokrator İsa\'nın ayakları dibinde tam secdeye kapanmış (proskynesis) halde betimlenen imparator kimdir?', 'VI. Leon', ['Büyük Konstantin', 'I. Justinianus', 'VIII. Mihail Paleologos'], 'İmparator Kapısı mozaiğinde Bilge lakaplı VI. Leon, İsa\'nın önünde en derin alçakgönüllülük ve yakarış pozu olan proskynesis durumunda gösterilmiştir.'),
  ('Bizans sanatında ortada İsa, sağında ve solunda ise insanlığın günahlarının bağışlanması için ellerini uzatarak şefaat dileyen Meryem Ana ile Vaftizci Yahya\'nın yer aldığı üçlü kompozisyona ne ad verilir?', 'Deesis (Yakarış / Şefaat)', ['Müjde (Evangelismos)', 'İsa\'nın Doğumu (Genesis)', 'Kudüs\'e Giriş (Vaioforos)'], 'Yunanca yakarış, dua anlamına gelen Deesis, Son Yargı sahnesinin çekirdeğini oluşturur; Meryem ve Vaftizci Yahya insanlık adına İsa\'ya aracılık eder.'),
  ('Doğu Hristiyan (Ortodoks) kiliselerinde cemaatin bulunduğu ana mekan (naos) ile din adamlarına ayrılmış kutsal sunak bölümü (bema) arasına yerleştirilen ve üzeri belirli bir düzende ikonalarla kaplı bölmeye ne ad verilir?', 'İkonostasis', ['Peristil revak', 'Ambon kürsüsü', 'Vaftiz kurnası'], 'Erken dönemdeki alçak templon korkuluklarının zamanla yükselip ikona dizileriyle kaplanması sonucu oluşan bölme duvarına ikonostasis denir.'),
  ('Eski Mısır sanatında timsah başlı olarak betimlenen, Nil Nehri\'nin gücünü ve bereketini simgeleyen ve Kom Ombo\'da Horus ile ortak tapınağı bulunan tanrı kimdir?', 'Sobek', ['Khnum', 'Ptah', 'Atum'], 'Fayyum ve Kom Ombo bölgelerinde kültü çok güçlü olan timsah başlı tanrı Sobek, Nil sularının hem tehlikesini hem de bereketini temsil eder.'),
  ('Eski Mısır\'da mumyalanmış bedenin veya heykelin görme, işitme, nefes alma ve beslenme duyularını öteki dünyada yeniden kazanması için rahiplerce keser benzeri bir aletle yapılan törene ne denir?', 'Ağız Açma Töreni', ['Kalp Tartımı Töreni', 'Sed Festivali', 'Opet Bayramı'], 'Tutankhamun\'un mezar duvarında halefi Ay tarafından uygulanırken de resmedilen "Ağız Açma" ritüeli, heykele ve mumyaya büyüsel yaşam soluğu kazandırırdı.'),
  ('Mezopotamya\'da Sümerlerin başkentlerinden Ur\'da İngiliz arkeolog Leonard Woolley tarafından keşfedilen ve Ur Standardı ile Kraliçe Puabi\'nin takılarını barındıran ünlü arkeolojik alan hangisidir?', 'Ur Kraliyet Mezarlığı', ['Krallar Vadisi', 'Alacahöyük Kral Mezarları', 'Gordion Tümülüsü'], 'MÖ 2600-2500 yıllarına tarihlenen Ur Kral Mezarları, altın miğferler (Meskalamdug), boğa başlı lirler ve toplu refakatçi gömüleriyle Erken Hanedanlar Dönemi Sümer sanatının hazinesidir.'),
  ('Babil İştar Kapısı\'nda ejderha (Muşhuşşu) sıralarıyla dönüşümlü olarak yer alan yaban öküzü (boğa) kabartmaları hangi Mezopotamya tanrısını temsil eder?', 'Fırtına ve Yağmur Tanrısı Adad\'ı', ['Bilgelik Tanrısı Ea\'yı', 'Veba Tanrısı Erra\'yı', 'Çoban Tanrısı Dumuzi\'yi'], 'İştar Kapısı\'nda üç kutsal hayvan birleşir: Tören Yolu\'ndaki aslanlar İştar\'ı, kapıdaki ejderhalar Marduk\'u, boğalar ise Fırtına Tanrısı Adad\'ı simgeler.'),
  ('Anadolu\'da Hitit İmparatorluğu yıkıldıktan sonra Güneydoğu Anadolu ve Kuzey Suriye\'de kurulan Kargamış, Malatya (Arslantepe), Zincirli ve Karatepe gibi merkezlere sanat tarihinde ne ad verilir?', 'Geç Hitit Kent Devletleri', ['İyonya Deniz Kolonileri', 'Doğu Roma Eyaletleri', 'Eski Tunç Çağı Beylikleri'], 'MÖ 1200 civarında Hattuşa\'nın çöküşünden sonra Hitit kültür ve hiyeroglif geleneğini Asur ve Arami etkileriyle harmanlayarak sürdüren krallıklara Geç Hitit Kent Devletleri denir.'),
  ('Eski Mısır\'da ölülerin mumyalarının içine konulduğu, insan vücudu ve yüzü biçiminde şekillendirilip parlak renklerle boyanan tabut tipine ne ad verilir?', 'Antropoid (İnsan biçimli) tabut / lahit', ['Küp blok ostotek', 'Pişmiş toprak küp mezar', 'Üçgen alınlıklı ev lahit'], 'Orta Krallık\'tan itibaren dikdörtgen sandık tabutların yerini alan antropoid (mumya biçimli) ahşap, kartonaj ve taş tabutlar, ölünün yüz maskesini ve koruyucu tanrı resimlerini taşır.'),
  ('Gize\'deki Büyük Keops Piramidi\'nin hemen yanındaki çukurlarda parçalar hâlinde gömülü bulunan ve sedir ağacından ip dikişli geçme tekniğiyle yapılmış kırk üç metrelik tekneye ne ad verilir?', 'Güneş Teknesi', ['Argo Gemisi', 'Uluburun Batığı', 'Nuh\'un Gemisi'], 'Firavunun ruhunun Güneş Tanrısı Ra ile birlikte gökyüzü okyanusunda yolculuk yapması (veya cenaze alayında taşınması) için gömülen Lübnan sediri Khufu Güneş Teknesi, Mısır ahşap mühendisliğinin şaheseridir.'),
  ('Roma\'daki Pantheon Tapınağı\'nın giriş revağı (portiko) alınlığında yer alan Latince yazıtta tapınağın ilk banisi olarak kimin adı yazılıdır?', 'Marcus Agrippa', ['İmparator Nero', 'Jül Sezar', 'Marcus Tullius Cicero'], 'Pantheon MS 2. yüzyılda İmparator Hadrianus tarafından bugünkü kubbeli haliyle yeniden inşa edilmiş olsa da Hadrianus saygı gereği ilk tapınağı MÖ 27\'de yaptıran Marcus Agrippa\'nın yazıtını korumuştur.'),
  ('Roma mimarisinde kireç, su, taş kırıkları ve "pozzolana" adı verilen volkanik külün karıştırılmasıyla elde edilen ve kubbe-tonoz devrimini mümkün kılan yapı malzemesi nedir?', 'Roma betonu', ['Güneşte kurutulmuş kerpiç tuğla', 'Dövme bronz kenetli kesme granit', 'Sırlı pişmiş toprak levha'], 'Vezüv çevresinden çıkarılan pozzolana volkanik külü, su altında bile sertleşebilen çok dayanıklı Roma harcını ve betonunu (opus caementicium) yaratmıştır.'),
  ('Antik Roma\'da varlıklı ailelerin şehir içindeki avlulu müstakil konutlarına verilen ad nedir ve Pompei fresklerinin büyük bölümü bu yapıların hangi kısımlarında bulunmuştur?', 'Domus adı verilir; atrium ve peristil çevresindeki kabul ve yemek odalarında bulunmuştur', ['İnsula adı verilir; yalnızca çok katlı kiralık apartmanların bodrum depolarında bulunmuştur', 'Tholos adı verilir; yuvarlak mezar odalarının dış saçaklarında bulunmuştur', 'Castrum adı verilir; askeri kışla surlarının burçlarında bulunmuştur'], 'Pompei\'deki zengin konutları olan domus\'larda duvar resimleri atrium (orta salon), tablinum (çalışma/kabul odası) ve triclinium (yemek odası) duvarlarını süslemiştir.'),
  ('Roma\'daki "Antoninus Pius Sütunu" kaidesinde, ölen imparator ve eşi Faustina\'nın kanatlı bir figürün sırtında gökyüzüne yükselişini betimleyen sahneye ne ad verilir?', 'Apotheosis (Tanrılaştırma / Göğe Yükseliş)', ['Proskynesis (Secdeye Kapanma)', 'Traditio Legis (Yasanın Teslimi)', 'Koimesis (Meryem\'in Uykusu)'], 'Antoninus Pius Sütunu kaidesinin bir yüzünde klasik düzenle imparatorluk çiftinin tanrılaştırılışı (apotheosis), diğer yüzünde ise süvarilerin cenaze geçidi (decursio) yer alır.'),
  ('Erken Hristiyan mimarisinde kilisenin batı girişinde yer alan, henüz vaftiz olmamış adayların (katekhumenlerin) veya tövbekârların beklediği enlemesine giriş holüne ne ad verilir?', 'Narteks', ['Apsis', 'Bema', 'Pastoforyon'], 'Bazilika ve Bizans kiliselerinde ana ibadet mekanına (naos) geçmeden önceki giriş koridoruna iç narteks (esonarteks) ve dış narteks (eksonarteks) adı verilir.'),
  ('Bizans İmparatoru I. Justinianus tarafından İstanbul\'da Ayasofya\'dan birkaç yıl önce (527-536) inşa ettirilen, sekizgen kubbeli merkezi planıyla San Vitale\'ye benzeyen ve halk arasında "Küçük Ayasofya" olarak bilinen yapı hangisidir?', 'Aziz Sergios ve Bakhos Kilisesi', ['Aya İrini Kilisesi', 'Hora Manastırı Kilisesi', 'Studios Manastırı Bazilikası'], 'Küçük Ayasofya Camii (Sergios ve Bakhos Kilisesi), merkezdeki sekiz payeli dilimli kubbesi ve kabartma yazılı arşitrav kuşağıyla Justinianus döneminin öncü yapılarındandır.'),
  ('Hristiyan geleneğinde insan eliyle yapılmadığına, İsa\'nın yüzünü sildiği keten beze (Mandylion) mucizevi biçimde çıktığına inanılan kutsal tasvirlere Yunanca ne ad verilir?', 'Akheiropoietos', ['İkonostasis', 'Tetramorf', 'Pantokrator'], '"El değmeden / insan eliyle yapılmamış" anlamına gelen Akheiropoietos kavramı (Urfa/Edessa Mandylionu gibi), İkonodulların ikonaların meşruiyetini savunurken kullandıkları en güçlü kanıtlardan biri olmuştur.'),
  ('Orta Bizans döneminde Konstantinopolis\'ten ihraç edilen veya diplomatik hediye olarak gönderilen, ince altın levhalar arasına renkli cam hamuru dökülüp fırınlanmasıyla yapılan zarif kuyumculuk ve ikona tekniğine ne ad verilir?', 'Bölmeli mine (Cloisonné emaye)', ['Sıcak balmumu (Enkostik)', 'Kazıma sgraffito seramik', 'Kuru sıva (Fresco secco)'], 'Bizans mine (cloisonné) sanatı; altın şeritlerle oluşturulan milimetrik odacıklara renkli toz cam doldurulup eritilmesiyle Venedik San Marco\'daki Pala d\'Oro gibi başyapıtlar ortaya koymuştur.'),
  ('Bizans sanatında Meryem Ana\'nın ölüm döşeginde uzanışı, çevresinde havarilerin yas tutuşu ve tam ortada beliren İsa\'nın annesinin ruhunu kundaklı bir bebek biçiminde kucağına alışını betimleyen sahneye ne ad verilir?', 'Koimesis (Meryem\'in Uykusu / Ölümü)', ['Evangelismos (Meryem\'e Müjde)', 'Hypapante (Tapınağa Takdim)', 'Metamorfoz (Başkalaşım)'], 'Ortodoks inancında Meryem\'in ölümü bir "uykuya dalış" (Koimesis) olarak adlandırılır; Kariye\'nin naos batı kapısı üzerindeki mozaikte İsa annesinin lekesiz ruhunu beyaz kundaklı bebek olarak taşır.'),
  ('Erken Hristiyan sanatında İmparator Konstantin\'in gördüğü rüya/vizyon sonrasında askeri sancaklara ve lahitlere işlenen, Yunanca "Khristos" (Mesih) kelimesinin ilk iki harfi olan X (Khi) ve P (Rho) harflerinin üst üste geçirilmesiyle oluşan monogramın adı nedir?', 'Khi-Rho', ['Alfa ve Omega', 'Ankh Haçı', 'Gamalı Haç'], 'Yunanca Khi (X) ve Rho (P) harflerinin birleşimi olan Khi-Rho monogramı, Konstantin\'in Milvian Köprüsü Savaşı\'ndan itibaren Hristiyanlığın zafer sembolü olarak yaygınlaşmıştır.'),
  ('İstanbul\'da İmparator V. Konstantinos veya Justinianus döneminden kalan, 336 adet devşirme sütunu ve ters çevrilmiş iki "Medusa Başı" sütun kaidesiyle ünlü yer altı Bizans su yapısı hangisidir?', 'Yerebatan Sarnıcı (Bazilika Sarnıcı)', ['Binbirdirek Sarnıcı (Filoksenos)', 'Zeyrek Sarnıcı', 'Bozdoğan Su Kemeri'], 'I. Justinianus tarafından 532 Nika İsyanı sonrasında genişletilerek inşa edilen Yerebatan Sarnıcı, antik yapılardan devşirilmiş (spolia) sütun başlıkları ve iki dev Medusa blokuyla ünlüdür.'),
  ('Antik Roma\'da su kaynaklarını vadiler ve ovalar üzerinden hafif ve sabit bir eğimle şehirlere, çeşmelere ve hamamlara taşıyan çok katlı kemerli mühendislik yapılarına ne ad verilir?', 'Su kemeri', ['Zafer takı', 'Bazilika', 'Peristil'], 'Fransa\'daki Pont du Gard, İspanya\'daki Segovia ve İstanbul\'daki Valens (Bozdoğan) Su Kemeri, Roma su mühendisliğinin anıtsal akuadük örnekleridir.'),
  ('Pompei ve Roma evlerinin giriş eşiğindeki taban mozaiklerinde evi koruyan zincirli bir köpek figürünün yanına yazılan ünlü Latince uyarı ifadesi nedir?', 'Cave Canem (Köpekten Sakın / Dikkat Köpek Var)', ['Carpe Diem (Günü Yakala)', 'Veni Vidi Vici (Geldim Gördüm Yendim)', 'Pax Romana (Roma Barışı)'], 'Pompei\'deki Trajik Şair Evi girişinde bulunan siyah-beyaz tesseralı "Cave Canem" mozaiği, Roma gündelik yaşam sanatının en bilinen simgelerindendir.'),
  ('Bizans İmparatorluğu\'nda yalnızca imparatorluk sarayındaki "Porphyrogennetos" (Mor Odada Doğanlar) unvanlı hanedan üyeleriyle özdeşleştirilen ve Mısır ocaklarından çıkarılan koyu mor-bordo renkli sert volkanik imparatorluk taşı hangisidir?', 'Porfir', ['Beyaz Paros mermeri', 'Sarı kehribar taşı', 'Yeşil malakit taşı'], 'İmparator Konstantin\'in Çemberlitaş\'ı, İstanbul Arkeoloji Müzeleri\'ndeki imparator lahitleri ve Ayasofya zemini üzerindeki "Omphalion" halkalarında kullanılan erguvani porfir taşı mutlak hükümdarlık simgesiydi.'),
  ('Bizans ve Erken Hristiyan mimarisinde kilisenin doğu ucunda yer alan, genellikle yarım daire (içten) veya çokgen (dıştan) planlı olup üzeri yarım kubbeyle örtülü kutsal sunak nişine ne ad verilir?', 'Apsis', ['Atrium', 'Narteks', 'Transept'], 'Kiliselerde kıble yönü gibi ibadetin yöneldiği doğu cephesindeki çıkıntılı yarım kubbeli kutsal bölüme apsis denir.'),
  ('İstanbul\'da Bozdoğan Kemeri yakınında yer alan, Komnenos Hanedanı döneminde (12. yüzyıl) yan yana inşa edilmiş üç kiliseden oluşan ve hanedan üyelerinin anıt mezarlarını barındıran yapı topluluğu hangisidir?', 'Zeyrek Camii (Pantokrator Manastırı Kilisesi)', ['Eski İmaret Camii (Pantepoptes)', 'Bodrum Camii (Mirelaion)', 'Gül Camii (Azize Theodosia)'], 'İmparator II. İoannes Komnenos ve eşi İrene tarafından kurulan Pantokrator Manastırı (Zeyrek Camii), İstanbul\'da Ayasofya\'dan sonra ayakta kalan en büyük Bizans dini kompleksi olup zengin opus sectile taban döşemelerine sahiptir.'),
  ('Bizans ikona ve mozaiklerinde İsa, Meryem, melekler ve azizlerin başlarının çevresini saran, kutsallığı ve ilahi nuru simgeleyen altın sarısı dairesel ışığa ne ad verilir?', 'Hale', ['Mandorla', 'Oculus', 'Tessera'], 'Antik sanatta güneş tanrıları ve imparatorlar için kullanılan ışık halesi (nimbus), Hristiyan sanatında kutsal kişilerin başını çevreler; yalnızca İsa\'nın halesinin içinde haç kolları (haçlı hale) yer alır.'),
  ('Bizans ikona ve mozaiklerinde Meryem Ana figürünün iki yanında standart olarak kısaltılmış biçimde yazılan Yunanca "ΜΡ ΘΥ" harfleri hangi unvanın kısaltmasıdır?', 'Meter Theou (Tanrı\'nın Annesi)', ['Maria Regina (Kraliçe Meryem)', 'Magna Mater (Ulu Ana)', 'Memoria Christi (Mesih\'in Hatırası)'], 'Özellikle İkonoklazm sonrasında tüm Meryem ikonalarında zorunlu bir kimlik yazıtı haline gelen ΜΡ ΘΥ, Yunanca "Meter Theou" (Tanrı Anası) ifadesinin ilk ve son harflerinden oluşan kısaltmadır (nomina sacra).'),
  ('Roma İmparatoru Hadrianus tarafından MS 2. yüzyılda kendisi ve ailesi için Tiber Nehri kıyısında silindirik dev bir anıt mezar olarak inşa ettirilen ve Orta Çağ\'da papalık kalesine dönüştürülen yapı hangisidir?', 'Hadrianus Mozolesi', ['Pantheon Tapınağı', 'Kolezyum Arenası', 'Marcellus Tiyatrosu'], 'Bugün Roma\'da Castel Sant\'Angelo olarak bilinen silindirik yapı, İmparator Hadrianus\'un Augustus Mozolesi\'ne rakip olarak yaptırdığı görkemli hanedan türbesidir.'),
  ('1453 sonrasında Girit Adası\'nda Venedik yönetimi altında çalışan ve Bizans ikona geleneğini İtalyan Rönesans etkileriyle harmanlayıp sonradan İspanya\'ya yerleşen dünyaca ünlü Girit Okulu kökenli ressam kimdir?', 'El Greco', ['Sandro Botticelli', 'Albrecht Dürer', 'Jan van Eyck'], 'Gençliğinde Girit\'te geleneksel Bizans (Post-Bizans) tarzında yumurta temperasıyla usta bir ikona ressamı ("Doménikos") olarak yetişen El Greco, uzamış ruhani figürlerini ve dramatik ışığını Venedik ve Toledo\'ya taşımıştır.'),
];
